begin;
update public.wonder_species set active = false where active and slug not in ('daisy', 'chrysanthemum', 'aster', 'goldenrod', 'calendula', 'japanese_anemone', 'sedum', 'helenium', 'celosia', 'salvia', 'nasturtium', 'autumn_crocus', 'toad_lily');
update public.wonder_shop_items set active = false where active and item_key not in ('slot_2', 'slot_3', 'classic_cream', 'meadow_dots', 'blue_vine');
commit;
